export interface Stage {
  title: string;
  items: string[];
}

export interface ScenarioText {
  title: string;
  summary: string;
  problem: string;
  assumptions: string[];
  constraints: string[];
  stages: Stage[];
  interfaces: { from: string; to: string; via: string }[];
  dataFlow: string[];
  security: string[];
  approvals: string[];
  phases: { title: string; text: string }[];
  limitations: string[];
  tradeoffs: string[];
}

export interface PatternText {
  title: string;
  summary: string;
  description: string;
  whenToUse: string[];
  whenNotToUse: string[];
  stages: Stage[];
  prerequisites: string[];
  securityControls: string[];
  failureModes: { mode: string; mitigation: string }[];
  observability: string[];
  statusNote: string;
}

const st = (title: string, ...items: string[]): Stage => ({ title, items });
